package com.seaoftales.identity.service;
import com.seaoftales.storage.ImageStorageService;
import com.seaoftales.content.enums.Language; import com.seaoftales.identity.entity.*; import com.seaoftales.identity.enums.*; import com.seaoftales.identity.repository.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.transaction.support.TransactionSynchronization; import org.springframework.transaction.support.TransactionSynchronizationManager;
@Service public class IdentityService {
 private static final Logger log=LoggerFactory.getLogger(IdentityService.class);
 private final UserRepository users; private final InvitationRepository invitations; private final PendingRegistrationRepository pending; private final PasswordEncoder encoder; private final OtpService otp; private final EmailService emailService; private final ImageStorageService imageStorage; private final String publicBaseUrl;
 public IdentityService(UserRepository u,InvitationRepository i,PendingRegistrationRepository p,PasswordEncoder e,OtpService o,EmailService mail,ImageStorageService imageStorage,@org.springframework.beans.factory.annotation.Value("${seaoftales.public-base-url:}") String baseUrl){users=u;invitations=i;pending=p;encoder=e;otp=o;emailService=mail;this.imageStorage=imageStorage;publicBaseUrl=baseUrl;}
 public User find(String n){return users.findByUsername(n).orElseThrow();}
 private void validate(String n,String e,String p){if(n==null||!n.matches("[A-Za-z0-9_]{3,50}")||e==null||!e.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")||p==null||p.length()<8)throw new IllegalArgumentException("Invalid registration.");if(users.existsByUsername(n)||users.existsByEmail(e))throw new IllegalStateException("Account already exists.");}
 @Transactional public void register(String n,String e,String p){register(n,e,p,null);}
 @Transactional public void register(String n,String e,String p,String profilePicture){validate(n,e,p);savePending(n,e,p,PendingRegistrationType.READER,null,null,profilePicture);otp.issue(e,OtpPurpose.REGISTRATION);}
 public String registrationError(RuntimeException e){if(e instanceof IllegalArgumentException&&"Invalid registration.".equals(e.getMessage()))return "Please enter a valid username, email, and password of at least 8 characters.";if(e instanceof IllegalArgumentException&&e.getMessage()!=null&&e.getMessage().contains("different email"))return "Use the email address that received this invitation.";if(e instanceof IllegalStateException&&e.getMessage()!=null&&e.getMessage().contains("Account already exists"))return "This username or email is already in use.";if(e.getMessage()!=null&&e.getMessage().contains("wait before"))return "A verification code has already been sent. Please check your email.";if(e.getMessage()!=null&&e.getMessage().toLowerCase().contains("mail"))return "We couldn't send the verification email. Please try again later.";return "Registration could not be started. Please try again.";}
 @Transactional public void registerInvitation(String raw,InvitationType t,String n,String e,String p,Language l){registerInvitation(raw,t,n,e,p,l,null);}
 @Transactional public void registerInvitation(String raw,InvitationType t,String n,String e,String p,Language l,String profilePicture){if(t==null)throw new IllegalArgumentException("Invalid invitation.");Invitation i=valid(raw,t);String normalizedEmail=normalizeEmail(e);validate(n,normalizedEmail,p);if(t==InvitationType.AUTHOR&&i.getRecipientEmail()!=null&&!i.getRecipientEmail().equals(normalizedEmail))throw new IllegalArgumentException("This invitation was sent to a different email address.");if(t==InvitationType.AUTHOR&&l==null)throw new IllegalArgumentException("Please select a preferred language.");PendingRegistrationType pt=t==InvitationType.AUTHOR?PendingRegistrationType.AUTHOR:PendingRegistrationType.EDITOR;savePending(n,normalizedEmail,p,pt,l,i.getId(),profilePicture);otp.issue(normalizedEmail,t==InvitationType.AUTHOR?OtpPurpose.AUTHOR_REGISTRATION:OtpPurpose.EDITOR_REGISTRATION,l);}
 private void savePending(String n,String e,String p,PendingRegistrationType t,Language l,Long invitationId,String profilePicture){var x=pending.findTopByEmailAndConsumedFalseOrderByCreatedAtDesc(e).orElseGet(PendingRegistration::new);if(users.existsByUsername(n)||users.existsByEmail(e))throw new IllegalStateException("Account already exists.");String previous=x.getProfilePicture();x.setUsername(n);x.setEmail(e);x.setPasswordHash(encoder.encode(p));x.setType(t);x.setPreferredLanguage(l);x.setInvitationId(invitationId);x.setProfilePicture(profilePicture);x.setExpiresAt(Instant.now().plus(Duration.ofMinutes(30)));x.setConsumed(false);pending.save(x);if(previous!=null&&!previous.equals(profilePicture))deferCleanup(previous);}
 private void deferCleanup(String reference){Runnable cleanup=()->{try{if(!users.existsByProfilePicture(reference)&&!pending.existsByProfilePictureAndConsumedFalse(reference))imageStorage.delete(reference);}catch(RuntimeException ex){log.warn("Could not clean up superseded profile picture reference",ex);}};if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){cleanup.run();}});else cleanup.run();}
 @Transactional public void verifyRegistration(String email,String code){var x=pending.findTopByEmailAndConsumedFalseOrderByCreatedAtDesc(email).orElseThrow(()->new IllegalArgumentException("Registration not found or expired."));if(x.getExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Registration expired.");Invitation invitation=null;if(x.getInvitationId()!=null){invitation=invitations.findByIdForUpdate(x.getInvitationId()).orElseThrow(()->new IllegalArgumentException("Invalid or expired invitation."));if(invitation.isUsed()||invitation.getExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Invalid or expired invitation.");}OtpPurpose purpose=switch(x.getType()){case READER->OtpPurpose.REGISTRATION;case AUTHOR->OtpPurpose.AUTHOR_REGISTRATION;case EDITOR->OtpPurpose.EDITOR_REGISTRATION;};if(users.existsByUsername(x.getUsername())||users.existsByEmail(x.getEmail()))throw new IllegalStateException("Account already exists.");otp.verify(email,purpose,code);User u=new User();u.setUsername(x.getUsername());u.setEmail(x.getEmail());u.setPasswordHash(x.getPasswordHash());u.setRole(x.getType()==PendingRegistrationType.READER?UserRole.READER:x.getType()==PendingRegistrationType.AUTHOR?UserRole.AUTHOR:UserRole.EDITOR);u.setPreferredLanguage(x.getPreferredLanguage());u.setProfilePicture(x.getProfilePicture());u.setEnabled(true);users.save(u);if(invitation!=null){invitation.setUsed(true);invitation.setUsedAt(Instant.now());invitations.save(invitation);}x.setConsumed(true);pending.save(x);}
 public void resend(String email,OtpPurpose purpose){if(purpose==OtpPurpose.AUTHOR_REGISTRATION||purpose==OtpPurpose.EDITOR_REGISTRATION){var registration=pending.findTopByEmailAndConsumedFalseOrderByCreatedAtDesc(email).orElseThrow(()->new IllegalArgumentException("Registration not found or expired."));OtpPurpose expected=registration.getType()==PendingRegistrationType.AUTHOR?OtpPurpose.AUTHOR_REGISTRATION:registration.getType()==PendingRegistrationType.EDITOR?OtpPurpose.EDITOR_REGISTRATION:null;if(expected!=purpose||registration.getExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Registration not found or expired.");if(registration.getInvitationId()!=null)validInvitationId(registration.getInvitationId());otp.issue(email,purpose,registration.getPreferredLanguage()==null?Language.ENGLISH:registration.getPreferredLanguage());return;}otp.issue(email,purpose);}
 private void validInvitationId(Long id){Invitation i=invitations.findById(id).orElseThrow(()->new IllegalArgumentException("Invalid or expired invitation."));if(i.isUsed()||i.getExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Invalid or expired invitation.");}
 public void requestReset(String id){User u=users.findByUsername(id).orElseGet(()->users.findByEmail(id));if(u!=null)otp.issue(u.getEmail(),OtpPurpose.PASSWORD_RESET);}
 @Transactional public void resetPassword(String id,String code,String p){if(p==null||p.length()<8)throw new IllegalArgumentException("Invalid password.");User u=users.findByUsername(id).orElseGet(()->users.findByEmail(id));if(u==null)throw new IllegalArgumentException("Invalid reset request.");otp.verify(u.getEmail(),OtpPurpose.PASSWORD_RESET,code);u.setPasswordHash(encoder.encode(p));users.save(u);}
 public Invitation valid(String raw,InvitationType t){Invitation i=invitations.findByTokenHash(hash(raw==null?"":raw)).orElseThrow(()->new IllegalArgumentException("Invalid invitation."));if(i.getType()!=t||i.isUsed()||i.getExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Invalid or expired invitation.");return i;}
 @Transactional public CreatedInvitation createAuthorInvitation(String recipientEmail,Language language,String requestOrigin){String normalized=normalizeAndValidateEmail(recipientEmail);if(language==null)throw new IllegalArgumentException("Please select a preferred language.");CreatedInvitation created=createInvitationRecord(InvitationType.AUTHOR,normalized,language);return deliver(created,normalized,language,requestOrigin);}
 @Transactional public CreatedInvitation resendAuthorInvitation(String raw,String requestOrigin){Invitation invitation=valid(raw,InvitationType.AUTHOR);if(invitation.getRecipientEmail()==null)throw new IllegalArgumentException("This invitation has no recipient email and cannot be resent.");Language language=invitation.getPreferredLanguage()==null?Language.JAPANESE:invitation.getPreferredLanguage();CreatedInvitation created=new CreatedInvitation(raw,invitation.getExpiresAt(),invitation.isUsed(),invitation.getRecipientEmail(),language,false);return deliver(created,invitation.getRecipientEmail(),language,requestOrigin);}
 private CreatedInvitation deliver(CreatedInvitation created,String recipientEmail,Language language,String requestOrigin){try{String base=publicBaseUrl==null||publicBaseUrl.isBlank()?requestOrigin:publicBaseUrl;if(base==null||base.isBlank())throw new IllegalStateException("Public site URL is not configured.");String url=base.replaceAll("/+$","")+"/invite/author?token="+java.net.URLEncoder.encode(created.token(),StandardCharsets.UTF_8);emailService.sendAuthorInvitation(recipientEmail,url,created.expiresAt(),language);return new CreatedInvitation(created.token(),created.expiresAt(),created.used(),recipientEmail,language,true);}catch(RuntimeException e){return new CreatedInvitation(created.token(),created.expiresAt(),created.used(),recipientEmail,language,false);}}
 private CreatedInvitation createInvitationRecord(InvitationType t,String recipientEmail,Language language){byte[]b=new byte[32];new SecureRandom().nextBytes(b);String s=Base64.getUrlEncoder().withoutPadding().encodeToString(b);Instant createdAt=Instant.now();Instant expiresAt=createdAt.plus(Duration.ofDays(3));Invitation i=new Invitation();i.setTokenHash(hash(s));i.setType(t);i.setRecipientEmail(recipientEmail);i.setPreferredLanguage(language);i.setExpiresAt(expiresAt);i.setCreatedAt(createdAt);invitations.save(i);return new CreatedInvitation(s,expiresAt,i.isUsed(),recipientEmail,language,false);}
 public CreatedInvitation createInvitation(InvitationType t){if(t==InvitationType.AUTHOR)throw new IllegalArgumentException("Author invitations require a recipient email.");return createInvitationRecord(t,null,null);}
 public record CreatedInvitation(String token,Instant expiresAt,boolean used,String recipientEmail,Language preferredLanguage,boolean emailSent){}
 public static String normalizeEmail(String email){return email==null?null:email.trim().toLowerCase(Locale.ROOT);}
 private String normalizeAndValidateEmail(String email){String normalized=normalizeEmail(email);if(normalized==null||!normalized.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Enter a valid recipient email address.");return normalized;}
 public void changePassword(String n,String c,String p){User u=find(n);if(!encoder.matches(c,u.getPasswordHash())||p==null||p.length()<8)throw new IllegalArgumentException("Invalid password.");u.setPasswordHash(encoder.encode(p));users.save(u);}
 public static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception x){throw new IllegalStateException(x);}}
}
